#!/bin/bash
#
# -----------------------------------------------------------------------------
# Step 4. Sensitivity analysis: leave-one-LD-block-out for HAR enrichment in
#         the primary S-LDSC model (ALL + BGS + HARs + NegNSS).
#
# For each LD block overlapping at least one HAR, the regression SNPs located
# within the block are removed from the summary statistics and the primary
# model is re-estimated with the same annotations and LD scores.
#
# Inputs (generated by 3_prepare_ldblocks.sh):
#   BLOCK_LIST    one block ID per line (blocks overlapping at least one HAR)
#   SNP_TO_BLOCK  two columns: SNP ID, block ID
#
# Usage:
#   bash 4_leave_one_ldblock_out.sh                 # all blocks in BLOCK_LIST
#   BLOCKS="block_12 block_13" bash 4_leave_one_ldblock_out.sh
#
# Note: the full analysis involves one S-LDSC run per block and phenotype
# (1,152 blocks x 4 phenotypes); running blocks in parallel is recommended.
# -----------------------------------------------------------------------------

set -euo pipefail

# ===== CONFIGURATION =========================================================
LDSC_DIR="${LDSC_DIR:-path/to/ldsc}"
SUMSTATS_DIR="${SUMSTATS_DIR:-path/to/munged_sumstats}"
CUSTOM_DIR="${CUSTOM_DIR:-ldscores/custom}"
WEIGHTS_PREFIX="${WEIGHTS_PREFIX:-path/to/weights_hm3_no_MHC/weights.hm3_noMHC.}"
FRQ_PREFIX="${FRQ_PREFIX:-path/to/1000G_Phase3_frq/1000G.EUR.QC.}"
BLOCK_LIST="${BLOCK_LIST:-loo_blocks/blocks_with_HARs.txt}"
SNP_TO_BLOCK="${SNP_TO_BLOCK:-loo_blocks/snp_to_block.txt}"
OUT_BASE="${OUT_BASE:-results/loo_blocks}"
BLOCKS="${BLOCKS:-$(cat "${BLOCK_LIST}")}"

# Phenotypes with significant HAR enrichment in the primary model
PHENOS=( adhd23 scz22 mdd25 int18 )
# =============================================================================

TMP=$(mktemp -d "${TMPDIR:-/tmp}/loo_XXXX")
trap 'rm -rf "${TMP}"' EXIT

for BLOCK in ${BLOCKS}; do
  echo ">> Excluding block ${BLOCK}"

  # SNPs to exclude for this block
  awk -v b="${BLOCK}" '$2==b {print $1}' "${SNP_TO_BLOCK}" > "${TMP}/exclude.txt"

  for PHENO in "${PHENOS[@]}"; do
    OUT_DIR="${OUT_BASE}/${PHENO}"
    mkdir -p "${OUT_DIR}"

    # Summary statistics without the SNPs of this block (header kept)
    zcat "${SUMSTATS_DIR}/${PHENO}_munged.sumstats.gz" | \
      awk 'NR==FNR {ex[$1]; next} FNR==1 || !($1 in ex)' "${TMP}/exclude.txt" - | \
      gzip > "${TMP}/${PHENO}.sumstats.gz"

    python "${LDSC_DIR}/ldsc.py" \
      --h2 "${TMP}/${PHENO}.sumstats.gz" \
      --ref-ld-chr "${CUSTOM_DIR}/ALL.,${CUSTOM_DIR}/BGS.,${CUSTOM_DIR}/HARs.,${CUSTOM_DIR}/NegNSS." \
      --w-ld-chr "${WEIGHTS_PREFIX}" \
      --overlap-annot \
      --frqfile-chr "${FRQ_PREFIX}" \
      --print-coefficients \
      --n-blocks 200 \
      --return-silly-things \
      --out "${OUT_DIR}/${PHENO}_without_${BLOCK}"
  done
done
